"""Drive the original and my build through their MCP servers (batched) and through `run --cmd`."""
import json, os, subprocess, tempfile, shutil

ORIG = '/workspace/executable'
MINE = os.environ.get('MINE', '/workspace/.claude/worktrees/agent-a185b0ca1c931365d/target/release/bimcraft-cli')

class MCP:
    def __init__(self, exe):
        self.exe = exe
        self.d = tempfile.mkdtemp(prefix='hydmcp')
        self.p = subprocess.Popen([exe, 'mcp'], cwd=self.d, stdin=subprocess.PIPE, stdout=subprocess.PIPE,
                                  stderr=subprocess.DEVNULL)
        self.n = 0
        self._send([{"jsonrpc": "2.0", "id": 0, "method": "initialize", "params": {"protocolVersion": "2025-06-18"}}])

    def _send(self, msgs):
        line = json.dumps(msgs, ensure_ascii=False) + '\n'
        self.p.stdin.write(line.encode('utf-8'))
        self.p.stdin.flush()
        out = self.p.stdout.readline()
        return json.loads(out)

    def calls(self, items, chunk=400):
        """items: list of (command, params-as-json-text or python value). Returns list of (is_err, text)."""
        res = []
        for i in range(0, len(items), chunk):
            part = items[i:i + chunk]
            msgs = []
            for j, (c, p) in enumerate(part):
                self.n += 1
                msgs.append({"jsonrpc": "2.0", "id": j + 1, "method": "tools/call",
                             "params": {"name": "execute", "arguments": {"command": c, "params": p}}})
            # raw text params: splice them in to keep exact number texts
            line = '[' + ','.join(self._msg_text(m, part[k][1]) for k, m in enumerate(msgs)) + ']\n'
            self.p.stdin.write(line.encode('utf-8'))
            self.p.stdin.flush()
            out = json.loads(self.p.stdout.readline())
            byid = {o['id']: o for o in out}
            for j in range(len(part)):
                o = byid[j + 1]
                if 'result' in o:
                    r = o['result']
                    t = r['content'][0]['text']
                    res.append((bool(r.get('isError')), t))
                else:
                    res.append((True, 'RPCERR ' + json.dumps(o.get('error'))))
        return res

    @staticmethod
    def _msg_text(m, p):
        if isinstance(p, RawJ):
            ptxt = p.t
        else:
            ptxt = json.dumps(p, ensure_ascii=False)
        c = json.dumps(m['params']['arguments']['command'])
        return ('{"jsonrpc":"2.0","id":%d,"method":"tools/call","params":{"name":"execute","arguments":{"command":%s,"params":%s}}}'
                % (m['id'], c, ptxt))

    def close(self):
        try:
            self.p.stdin.close(); self.p.wait(timeout=10)
        except Exception:
            self.p.kill()
        shutil.rmtree(self.d, ignore_errors=True)

class RawJ:
    """Params given as raw JSON text (to keep e.g. 1e400 or 1.0 as typed)."""
    def __init__(self, t): self.t = t
    def __repr__(self): return self.t

def canon(is_err, text):
    """Pretty JSON from MCP -> compact sorted text as `run` prints it (number texts kept)."""
    if is_err:
        return 'ERR ' + text
    return 'OK ' + compact(text)

def compact(t):
    # remove whitespace outside strings
    out = []; ins = False; esc = False
    for ch in t:
        if ins:
            out.append(ch)
            if esc: esc = False
            elif ch == '\\': esc = True
            elif ch == '"': ins = False
        else:
            if ch == '"': ins = True; out.append(ch)
            elif ch in ' \n\t\r': pass
            else: out.append(ch)
    return ''.join(out)

