def fl(b):
    return struct.unpack('<d', struct.pack('<q', b))[0]

def main():
    cmd, tpl, lo, hi = sys.argv[1], sys.argv[2], float(sys.argv[3]), float(sys.argv[4])
    m = MCP(ORIG)
    def ask(x):
        r = m.calls([(cmd, RawJ(tpl.replace('@', repr(x))))])[0]
        return canon(*r)
    rl, rh = ask(lo), ask(hi)
    if rl == rh:
        print('same at both ends:', rl[:200])
        return
    bl, bh = bits(lo), bits(hi)
    # works for positive floats
    while bh - bl > 1:
        mid = (bl + bh) // 2
        r = ask(fl(mid))
        if r == rl:
            bl = mid
        else:
            bh = mid
    print('last like lo:', repr(fl(bl)), ask(fl(bl))[:150])
    print('first like hi:', repr(fl(bh)), ask(fl(bh))[:150])
    m.close()

main()

