    for _ in 0..4 {
        let b = match self.peek() {
            None => return Err(self.err("EOF while parsing a string")),
            Some(b) => b,
        };
        self.i += 1;
        let d = match b {
            b'0'..=b'9' => b - b'0',
            b'a'..=b'f' => b - b'a' + 10,
            b'A'..=b'F' => b - b'A' + 10,
            _ => return Err(self.err("invalid escape")),
        };
        v = v * 16 + d as u16;
    }
    Ok(v)
}
fn parse_string(&mut self) -> Result<String, ParseError> {
    let mut out: Vec<u8> = Vec::new();
    loop {
        let b = match self.peek() {
            None => return Err(self.err("EOF while parsing a string")),
            Some(b) => b,
        };
        self.i += 1;
        match b {
            b'"' => break,
            b'\\' => {
                let e = match self.peek() {
                    None => return Err(self.err("EOF while parsing a string")),
                    Some(e) => e,
                };
                self.i += 1;
                match e {
                    b'"' => out.push(b'"'),
                    b'\\' => out.push(b'\\'),
                    b'/' => out.push(b'/'),
                    b'b' => out.push(8),
                    b'f' => out.push(12),
                    b'n' => out.push(b'\n'),
                    b'r' => out.push(b'\r'),
                    b't' => out.push(b'\t'),
