#!/usr/bin/env python3
"""sweep.py [-m] [-f] [-x k1,k2] [-k k1,k2] CMD 'template with @' v1 v2 ... | --range a b step:
the original's reply per value, collapsing runs of equal replies (prints value ranges).
-x drops keys from the reply before comparing; -k keeps only these keys."""
import sys, json
sys.path.insert(0, '/tmp/hydro-agent')
from lib import *
args = sys.argv[1:]
who = orig
full = False
drop = []
keep = None
while args and args[0].startswith('-') and args[0] in ('-m', '-f', '-x', '-k'):
    if args[0] == '-m':
        who = mine
        args = args[1:]
    elif args[0] == '-f':
        full = True
        args = args[1:]
    elif args[0] == '-x':
        drop = args[1].split(',')
        args = args[2:]
    elif args[0] == '-k':
        keep = args[1].split(',')
        args = args[2:]
cmd, tpl = args[0], args[1]
rest = args[2:]
if rest and rest[0] == '--range':
    a, b, st = float(rest[1]), float(rest[2]), float(rest[3])
    vals = []
    n = int(round((b - a) / st))
    for i in range(n + 1):
        v = a + i * st
        v = round(v, 10)
        vals.append(repr(v) if v != int(v) else str(int(v)))
else:
    vals = rest
items = [(cmd, RawJ(tpl.replace('@', v))) for v in vals]
res = who(items)

def shown(r):
    t = canon(*r)
    if t.startswith('OK ') and (drop or keep):
        o = json.loads(t[3:])
        for k in drop:
            o.pop(k, None)
        if keep:
            o = {k: o.get(k) for k in keep}
        return 'OK ' + json.dumps(o, separators=(',', ':'), sort_keys=True)
    return t

prev = None
start = None
last = None
for v, r in zip(vals, res):
    t = shown(r)
    if full:
        print(v, '=>', t)
        continue
    if t != prev:
        if prev is not None:
            print(f'{start} .. {last} => {prev[:400]}')
        prev = t
        start = v
    last = v
if not full and prev is not None:
    print(f'{start} .. {last} => {prev[:400]}')

