#!/usr/bin/env python3
"""Fit Colebrook constants to the original's water_size data."""
import sys, json, math
data = json.load(open('/tmp/hydro-agent/wdata.json'))
data = [d for d in data if len(d) == 6]

def colebrook(Re, rel, iters=200):
    # solve 1/sqrt(f) = -2 log10(rel/3.7 + 2.51/(Re sqrt f))
    x = 0.02 ** -0.5
    for _ in range(iters):
        x = -2 * math.log10(rel / 3.7 + 2.51 * x / Re)
    return 1 / (x * x)

def J(q_lps, d_mm, nu, eps_mm, g, laminar=None):
    D = d_mm / 1000
    A = math.pi * D * D / 4
    V = q_lps / 1000 / A
    Re = V * D / nu
    if laminar is not None and Re < laminar:
        f = 64 / Re
    else:
        f = colebrook(Re, eps_mm / d_mm)
    return f * V * V / (2 * g * D)

def score(nu, eps, g, laminar=None, lo_re=4000, verbose=False):
    worst = 0
    n = 0
    bad = 0
    for dn, q, j5, v, lk, di in data:
        D = di / 1000
        V = q / 1000 / (math.pi * D * D / 4)
        Re = V * D / nu
        if Re < lo_re:
            continue
        jj = J(q, di, nu, eps, g, laminar)
        lkp = round(jj * 1e6 * 9.81, 2)
        # compare against loss_kpa (more digits)
        jo = lk / 9.81e6
        rel = abs(jj - jo) / jo
        n += 1
        if abs(lkp - lk) > 0.011:
            bad += 1
        worst = max(worst, rel)
    return worst, n, bad

for nu in [1.0e-6, 1.003e-6, 1.004e-6, 1.0034e-6, 1.005e-6, 1.01e-6, 1.007e-6, 1.002e-6]:
    for eps in [0.0, 0.0015, 0.001, 0.002, 0.005, 0.007, 0.01, 0.0015e0]:
        for g in [9.81, 9.80665]:
            w, n, b = score(nu, eps, g)
            print(f'nu={nu} eps={eps} g={g}: worst rel {w:.3e} over {n}, bad {b}')

