#!/usr/bin/env python3
"""Exact-match tests of Colebrook variants against loss_kpa over 1e6 m and the 5-dp head loss."""
import sys, json, math
data = json.load(open('/tmp/hydro-agent/wdata.json'))
data = [d for d in data if len(d) == 6]
NU, EPS, G = 1.004e-6, 0.0015, 9.81

def r2(x):
    return round(x * 100) / 100

def rnd(x, n):
    m = 10 ** n
    return round(x * m) / m

def variants():
    def mk(start, iters, form, lam, area, jform):
        def J(q, di):
            D = di / 1000
            A = area(D)
            V = (q / 1000) / A
            Re = V * D / NU
            if Re < lam:
                f = 64 / Re
            else:
                rel = (EPS / 1000) / D if form[1] == 'm' else EPS / di
                x = start(Re, rel)
                if form[0] == 'x':
                    for _ in range(iters):
                        x = -2 * math.log10(rel / 3.7 + 2.51 / (Re * math.sqrt(1 / (x * x))) ) if False else -2 * math.log10(rel / 3.7 + 2.51 * x / Re)
                    f = 1 / (x * x)
                else:
                    f = x
                    for _ in range(iters):
                        f = (-2 * math.log10(rel / 3.7 + 2.51 / (Re * math.sqrt(f)))) ** -2
            return jform(f, V, D)
        return J
    starts = {
        'x0=1/sqrt(0.02)': lambda Re, rel: 0.02 ** -0.5,
        'swamee_x': lambda Re, rel: 1 / math.sqrt(0.25 / math.log10(rel / 3.7 + 5.74 / Re ** 0.9) ** 2),
    }
    fstarts = {
        'f0=0.02': lambda Re, rel: 0.02,
        'f0=swamee': lambda Re, rel: 0.25 / math.log10(rel / 3.7 + 5.74 / Re ** 0.9) ** 2,
    }
    areas = {'pi/4 D2': lambda D: math.pi / 4 * D * D, 'pi D2/4': lambda D: math.pi * D * D / 4,
             'pi (D/2)^2': lambda D: math.pi * (D / 2) ** 2, 'pi*D*D/4.0': lambda D: math.pi * D * D / 4.0}
    jforms = {'f/D V2/2g': lambda f, V, D: f / D * V * V / (2 * G), 'f V2/(2gD)': lambda f, V, D: f * V * V / (2 * G * D),
              'f*(1/D)*(V^2/(2g))': lambda f, V, D: f * (1 / D) * (V * V / (2 * G)),
              'f*V^2/(D*2g)': lambda f, V, D: f * V ** 2 / (D * 2 * G)}
    out = {}
    for sn, s in starts.items():
        for an, a in areas.items():
            for jn, jf in jforms.items():
                for it in (20, 50, 100):
                    out[f'x:{sn}:{an}:{jn}:{it}'] = mk(s, it, 'xm', 2300, a, jf)
    for sn, s in fstarts.items():
        for an, a in areas.items():
            for jn, jf in jforms.items():
                for it in (20, 50, 100):
                    out[f'f:{sn}:{an}:{jn}:{it}'] = mk(s, it, 'fm', 2300, a, jf)
    return out

res = []
for name, J in variants().items():
    ex = 0
    ex5 = 0
    n = 0
    for dn, q, j5, v, lk, di in data:
        try:
            j = J(q, di)
        except Exception:
            continue
        n += 1
        if r2(j * 1e6 * 9.81) == lk or r2(j * 1000000.0 * G) == lk:
            ex += 1
        if rnd(j, 5) == j5:
            ex5 += 1
    res.append((ex, ex5, n, name))
res.sort(reverse=True)
for r in res[:30]:
    print(r)

