best = variants()[res[0][3]]
for dn, q, j5, v, lk, di in data:
    j = best(q, di)
    if r2(j * 1e6 * 9.81) != lk:
        D = di / 1000
        V = q / 1000 / (math.pi / 4 * D * D)
        print('fail', dn, q, 'Re', V * D / NU, 'orig', lk, 'mine', r2(j * 1e6 * 9.81), j * 1e6 * 9.81)

