#!/usr/bin/env python3
"""trans.py CMD 'template with @' KEY lo hi step [tol]: positions where the original's KEY (a rounded reading)
changes as @ goes from lo to hi; bisected to tol. Prints (x_transition, value_before, value_after)."""
import sys, json
sys.path.insert(0, '/tmp/hydro-agent')
from lib import *

def transitions(cmd, tpl, key, lo, hi, step, tol=1e-7, m=None):
    own = m is None
    if own:
        m = MCP(ORIG)
    xs = []
    n = int(round((hi - lo) / step))
    for i in range(n + 1):
        xs.append(lo + i * step)

    def val(rs):
        out = []
        for r in rs:
            t = canon(*r)
            if t.startswith('OK '):
                o = json.loads(t[3:])
                out.append(o.get(key))
            else:
                out.append('ERR ' + t[4:60])
        return out

    def ask(vals):
        return val(m.calls([(cmd, RawJ(tpl.replace('@', repr(v)))) for v in vals]))

    ys = ask(xs)
    res = []
    pend = [(xs[i], xs[i + 1], ys[i], ys[i + 1]) for i in range(len(xs) - 1) if ys[i] != ys[i + 1]]
    # bisect all pending intervals in parallel
    while pend:
        mids = [(a + b) / 2 for a, b, _, _ in pend]
        ym = ask(mids)
        nxt = []
        for (a, b, ya, yb), mid, y in zip(pend, mids, ym):
            if y == ya:
                a = mid
            elif y == yb:
                b = mid
            else:
                # a further change inside: split
                nxt.append((mid, b, y, yb))
                b = mid
                yb = y
            if b - a <= tol * max(1.0, abs(a)):
                res.append((a, b, ya, yb))
            else:
                nxt.append((a, b, ya, yb))
        pend = nxt
    res.sort()
    if own:
        m.close()
    return res

if __name__ == '__main__':
    cmd, tpl, key, lo, hi, step = sys.argv[1], sys.argv[2], sys.argv[3], float(sys.argv[4]), float(sys.argv[5]), float(sys.argv[6])
    tol = float(sys.argv[7]) if len(sys.argv) > 7 else 1e-9
    for a, b, ya, yb in transitions(cmd, tpl, key, lo, hi, step, tol):
        print(f'{(a + b) / 2:.12f} {ya} {yb}')

