#!/usr/bin/env python3
"""Sample by_length (and by_depth) transitions over Q for each knot length / depth and outlet; save to files."""
import sys, json
sys.path.insert(0, '/tmp/hydro-agent')
from lib import *
from trans import transitions

m = MCP(ORIG)
what = sys.argv[1]
if what == 'len':
    for outlet in ['edge', 'funnel']:
        for L in [300, 600, 1000, 1500, 2000, 3000, 6000, 25000, 1000000000]:
