#!/usr/bin/env python3
"""Fit every by_length curve file as log Q = a + b log D + c log^2 D (ln and log10), using exact transition D values."""
import sys, math, glob
sys.path.insert(0, '/tmp/hydro-agent')
from segs import load
from polyfit import fit

def fitfile(fn, dmin=50.06, dmax=1e9, base=math.e):
    rows = [(y, x) for x, y in load(fn) if dmin <= y <= dmax]
    lg = (lambda v: math.log(v)) if base == math.e else (lambda v: math.log10(v))
    c = fit(rows, 2, lg, lg)
    ex = (lambda v: math.exp(v)) if base == math.e else (lambda v: 10 ** v)
    worst = max(abs(ex(c[0] + c[1] * lg(d) + c[2] * lg(d) ** 2) - q) / q for d, q in rows)
    return c, worst, len(rows)

if __name__ == '__main__':
    files = sys.argv[1:] or sorted(glob.glob('/tmp/hydro-agent/cl_*.txt'))
    for fn in files:
        for base in (math.e, 10):
            c, w, n = fitfile(fn, base=base)
            print('%-40s %s n=%d worst=%.2e  a=%.10g b=%.10g c=%.10g' % (fn.split('/')[-1], 'ln ' if base == math.e else 'lg ', n, w, c[0], c[1], c[2]))

