#!/usr/bin/env python3
"""Recover the L = infinity curves from the L = 1e9 mm samples, given the 25 m curve and a 1/L tail."""
import sys, math
sys.path.insert(0, '/tmp/hydro-agent')
from segs import load
from polyfit import fit

C25 = {'edge': (-2.783537, 2.265283, 0.01298375), 'funnel': (4.10884, -0.9274304, 0.3834927)}

def d_of_q(q, a, b, c):
    # ln q = a + b u + c u^2
    lq = math.log(q)
    if abs(c) < 1e-15:
        return math.exp((lq - a) / b)
    disc = b * b - 4 * c * (a - lq)
    u1 = (-b + math.sqrt(disc)) / (2 * c)
    u2 = (-b - math.sqrt(disc)) / (2 * c)
    # pick the root in a plausible range
    for u in (u1, u2):
        if 2.0 < u < 6.5:
            return math.exp(u)
    return math.exp(u1)

for outlet in ['edge', 'funnel']:
    rows = load('/tmp/hydro-agent/cl_%s_1000000000.txt' % outlet)
    w = 25000 / 1e9
    pts = []
    for q, dobs in rows:
        if dobs < 50.06:
            continue
        d25 = d_of_q(q, *C25[outlet])
        dinf = (dobs - w * d25) / (1 - w)
        pts.append((dinf, q, d25))
    for lo, hi in [(50, 200), (52, 200), (60, 200)]:
        sel = [(d, q) for d, q, _ in pts if lo <= d <= hi]
        c = fit(sel, 2, math.log, math.log)
        worst = max(abs(math.exp(c[0] + c[1] * math.log(d) + c[2] * math.log(d) ** 2) - q) / q for d, q in sel)
        print(outlet, lo, hi, 'n=%d worst=%.2e a=%.10g b=%.10g c=%.10g' % (len(sel), worst, c[0], c[1], c[2]))

