#!/usr/bin/env python3
"""Search arithmetic-order variants of water_size's head loss against loss_kpa over 1e6 m (exact matches)."""
import sys, json, math, itertools
data = json.load(open('/tmp/hydro-agent/wdata.json'))
data = [d for d in data if len(d) == 6]
NU, EPS_MM, G = 1.004e-6, 0.0015, 9.81

def rust_round(x):
    # f64::round: half away from zero
    return math.floor(x + 0.5) if x >= 0 else -math.floor(-x + 0.5)

def r2(x):
    y = x * 100
    fl = math.floor(y)
    d = y - fl
    if d > 0.5:
        r = fl + 1
    elif d < 0.5:
        r = fl
    else:
        r = fl + 1  # half away from zero (x positive)
    return r / 100

AREAS = {
    'pi/4*D*D': lambda D: math.pi / 4 * D * D,
    'pi*D*D/4': lambda D: math.pi * D * D / 4,
    'pi*(D/2)^2': lambda D: math.pi * (D / 2) * (D / 2),
    'pi*D^2/4': lambda D: math.pi * (D * D) / 4,
    '0.25*pi*D*D': lambda D: 0.25 * math.pi * D * D,
    'pi*0.25*D*D': lambda D: math.pi * 0.25 * D * D,
    'D*D*pi/4': lambda D: D * D * math.pi / 4,
    'pi/4*(D*D)': lambda D: math.pi / 4 * (D * D),
}
VELS = {
    'q/1000/A': lambda q, A: q / 1000 / A,
    'q/(1000A)': lambda q, A: q / (1000 * A),
    'q*1e-3/A': lambda q, A: q * 1e-3 / A,
    'q/A/1000': lambda q, A: q / A / 1000,
}
RES = {
    'V*D/nu': lambda V, D: V * D / NU,
    'D*V/nu': lambda V, D: D * V / NU,
}
RELS = {
    'eps/1000/D': lambda D, di: EPS_MM / 1000 / D,
    'eps/di': lambda D, di: EPS_MM / di,
    '1.5e-6/D': lambda D, di: 1.5e-6 / D,
}

def colebrook_x(Re, rel, form):
    x = 0.02 ** -0.5
    for _ in range(60):
        if form == 0:
            x = -2 * math.log10(rel / 3.7 + 2.51 * x / Re)
        elif form == 1:
            x = -2 * math.log10(rel / 3.7 + 2.51 / (Re / x))
        elif form == 2:
            x = -2.0 * math.log10(rel / 3.7 + 2.51 / Re * x)
    return x

def colebrook_f(Re, rel, form):
    f = 0.02
    for _ in range(60):
        if form == 0:
            f = (-2 * math.log10(rel / 3.7 + 2.51 / (Re * math.sqrt(f)))) ** -2
        elif form == 1:
            s = -2 * math.log10(rel / 3.7 + 2.51 / (Re * math.sqrt(f)))
            f = 1 / (s * s)
        elif form == 2:
            s = math.log10(rel / 3.7 + 2.51 / (Re * math.sqrt(f)))
            f = 0.25 / (s * s)
    return f

JS = {
    'f/D*V*V/(2g)': lambda f, V, D: f / D * V * V / (2 * G),
    'f*V*V/(2gD)': lambda f, V, D: f * V * V / (2 * G * D),
    'f*(1/D)*(V*V/(2g))': lambda f, V, D: f * (1 / D) * (V * V / (2 * G)),
    'f/D*(V*V/(2g))': lambda f, V, D: f / D * (V * V / (2 * G)),
    'f*V*V/(D*2g)': lambda f, V, D: f * V * V / (D * 2 * G),
    'f*V^2/2g/D': lambda f, V, D: f * (V * V) / (2 * G) / D,
    'f*V*V/2/g/D': lambda f, V, D: f * V * V / 2 / G / D,
    'f/D*V^2/(2g)': lambda f, V, D: f / D * (V * V) / (2 * G),
    '8fQ2/(g pi2 D5)': None,
}
LOSSES = {
    'J*L*9.81': lambda J, L: J * L * 9.81,
    'J*(L*9.81)': lambda J, L: J * (L * 9.81),
    '9.81*J*L': lambda J, L: 9.81 * J * L,
    'J*9.81*L': lambda J, L: J * 9.81 * L,
    'J*L*1000*9.81/1000': lambda J, L: J * L * 1000 * 9.81 / 1000,
    'J*L*9810/1000': lambda J, L: J * L * 9810 / 1000,
    'J*L*G*1000/1000': lambda J, L: J * L * G * 1000 / 1000,
}

def run():
    results = []
    cache = {}
    for (an, af), (vn, vf), (rn, rf), (ln, lf) in itertools.product(AREAS.items(), VELS.items(), RES.items(), RELS.items()):
        for cform in [('x', 0), ('x', 1), ('x', 2), ('f', 0), ('f', 1), ('f', 2)]:
            fs = []
            for dn, q, j5, v, lk, di in data:
                D = di / 1000
                A = af(D)
                V = vf(q, A)
                Re = rf(V, D)
                if Re < 2300:
                    f = 64 / Re
                else:
                    rel = lf(D, di)
                    if cform[0] == 'x':
                        x = colebrook_x(Re, rel, cform[1])
                        f = 1 / (x * x)
                    else:
                        f = colebrook_f(Re, rel, cform[1])
                fs.append((f, V, D, lk, q, A))
            for jn, jf in JS.items():
                if jf is None:
                    continue
                for lname, lfun in LOSSES.items():
                    ok = 0
                    for f, V, D, lk, q, A in fs:
                        J = jf(f, V, D)
                        if r2(lfun(J, 1e6)) == lk:
                            ok += 1
                    results.append((ok, an, vn, rn, ln, cform, jn, lname))
    results.sort(key=lambda r: -r[0])
    for r in results[:25]:
        print(r)
    print('total variants', len(results), 'of', len(data))

run()

