NU, EPS_MM, G = 1.004e-6, 0.0015, 9.81

def r2(x):
    y = x * 100
    fl = math.floor(y)
    d = y - fl
    r = fl + 1 if d >= 0.5 else fl
    return r / 100

def make(start, rule, tol, ret, maxit=100, form='x'):
    def f_of(Re, rel):
        if form == 'x':
            if start == 'f0.02':
                x = 1 / math.sqrt(0.02)
            elif start == 'x8':
                x = 8.0
            elif start == 'swamee':
                f0 = 0.25 / math.log10(rel / 3.7 + 5.74 / Re ** 0.9) ** 2
                x = 1 / math.sqrt(f0)
            elif start == 'haaland':
                x = -1.8 * math.log10((rel / 3.7) ** 1.11 + 6.9 / Re)
            elif start == 'f0.03':
                x = 1 / math.sqrt(0.03)
            elif start == 'f0.01':
                x = 1 / math.sqrt(0.01)
            for i in range(maxit):
                xn = -2 * math.log10(rel / 3.7 + 2.51 * x / Re)
                d = abs(xn - x)
                lim = tol if rule == 'abs' else tol * abs(xn)
                if d < lim:
                    x = xn if ret == 'new' else x
                    break
                x = xn
            return 1 / (x * x)
        else:
            if start == 'f0.02':
                f = 0.02
            elif start == 'swamee':
                f = 0.25 / math.log10(rel / 3.7 + 5.74 / Re ** 0.9) ** 2
            elif start == 'f0.03':
                f = 0.03
            elif start == 'f0.01':
                f = 0.01
            else:
                f = 0.02
            for i in range(maxit):
                s = -2 * math.log10(rel / 3.7 + 2.51 / (Re * math.sqrt(f)))
                fn = 1 / (s * s)
                d = abs(fn - f)
                lim = tol if rule == 'abs' else tol * abs(fn)
                if d < lim:
                    f = fn if ret == 'new' else f
                    break
                f = fn
            return f
    return f_of

def score(f_of, verbose=False):
    ok = 0
    bad = []
    for dn, q, j5, v, lk, di in data:
        D = di / 1000
        A = math.pi / 4 * D * D
        V = q / 1000 / A
        Re = V * D / NU
        if Re < 2300:
            f = 64 / Re
        else:
            f = f_of(Re, EPS_MM / 1000 / D)
        J = f / D * V * V / (2 * G)
        if r2(J * 1e6 * 9.81) == lk:
            ok += 1
        else:
            bad.append((dn, q, lk, J * 1e6 * 9.81))
    return ok, bad

res = []
for form in ['x', 'f']:
    for start in ['f0.02', 'swamee', 'f0.03', 'f0.01', 'x8', 'haaland']:
        if form == 'f' and start in ('x8', 'haaland'):
            continue
        for rule in ['abs', 'rel']:
            for tol in [1e-6, 1e-8, 1e-9, 1e-10, 1e-11, 1e-12, 1e-13, 1e-14, 1e-15, 0.0]:
                for ret in ['new', 'old']:
                    ok, bad = score(make(start, rule, tol, ret, form=form))
                    res.append((ok, form, start, rule, tol, ret))
    for start in ['f0.02', 'swamee', 'f0.03', 'f0.01']:
        for n in range(1, 31):
