#!/usr/bin/env python3
"""Random water_size cases compared between the original and mine (MCP)."""
import sys, random, json
sys.path.insert(0, '/tmp/hydro-agent')
from lib import *
from rnd_drain import BAD, num_text

FIX = ['wc', 'lav', 'sink', 'shower', 'laundry']
FIT = ['elbow90', 'elbow45', 'tee_through', 'tee_side', 'gate', 'globe', 'check']

def obj_counts(r, names, extra_names):
    d = {}
    for n in names:
        if r.random() < 0.5:
            d[n] = r.choice([0, 1, 2, 3, r.randint(0, 20), r.randint(0, 300), r.randint(0, 10000), 1.0, 2.0])
    parts = ['"%s":%s' % (k, num_text(v)) for k, v in d.items()]
    if r.random() < 0.05:
        parts.append('"%s":1' % r.choice(extra_names))
    if r.random() < 0.05:
        parts.append('"%s":%s' % (r.choice(names), r.choice(BAD)))
    r.shuffle(parts)
    return '{' + ','.join(parts) + '}'

def case(r):
    parts = []
    k = r.random()
    if k < 0.45:
        parts.append(('flow', num_text(r.choice([round(r.uniform(0.01, 3), 2), round(r.uniform(0.001, 30), 3),
                                                  r.choice([0.1, 0.2, 0.5, 1, 2, 3, 5, 10, 20]),
                                                  r.uniform(0, 1000), 1e-300, 1000, 0.68094]))))
    elif k < 0.9:
        parts.append(('fixtures', obj_counts(r, FIX, ['bath', 'WC', 'bidet', 'aa', 'zz'])))
    elif k < 0.95:
        parts.append(('flow', num_text(round(r.uniform(0.01, 3), 2))))
        parts.append(('fixtures', obj_counts(r, FIX, ['bath'])))
    if r.random() < 0.4:
        parts.append(('method', json.dumps(r.choice(['weights', 'sum']))))
    if r.random() < 0.4:
        parts.append(('dn', num_text(r.choice([20, 25, 32, 40, 50, 60, 75, 85, 110, 30, 100, 0, 20.0]))))
    if r.random() < 0.7:
        parts.append(('length', num_text(r.choice([r.randint(0, 100) * 100, r.randint(0, 50000), r.uniform(0, 1e5),
                                                    r.randint(0, 1000000), 0, 1000000000]))))
    if r.random() < 0.5:
        parts.append(('fittings', obj_counts(r, FIT, ['bend', 'tee', 'valve', 'aa', 'zz'])))
    if r.random() < 0.5:
        parts.append(('pressure', num_text(r.choice([r.randint(0, 500), round(r.uniform(0, 500), 1), 100, 150, 10,
                                                      r.uniform(0, 100000), 0]))))
    if r.random() < 0.4:
        parts.append(('rise', num_text(r.choice([r.randint(-50, 50) * 100, r.randint(-20000, 20000), 1500, 3000,
                                                  -1500, r.uniform(-1e9, 1e9), 0]))))
    if r.random() < 0.12 and parts:
        i = r.randrange(len(parts))
        parts[i] = (parts[i][0], r.choice(BAD))
    if r.random() < 0.03:
        parts.append((r.choice(['foo', 'Flow', 'units', 'zzz', 'aaa', 'inside']), '1'))
    r.shuffle(parts)
    return '{' + ','.join('"%s":%s' % (k, v) for k, v in parts) + '}'

if __name__ == '__main__':
    n = int(sys.argv[1]) if len(sys.argv) > 1 else 5000
    seed = int(sys.argv[2]) if len(sys.argv) > 2 else 1
    r = random.Random(seed)
    items = [('water_size', RawJ(case(r))) for _ in range(n)]
    compare(items, verbose=25, label='water')

