        '2acos(1-2*(2/3))': 2 * math.acos(1 - 2 * (2 / 3)),
        '2acos(1-4/3)': 2 * math.acos(1 - 4 / 3),
        '2acos((0.5-2/3)/0.5)': 2 * math.acos((0.5 - 2 / 3) / 0.5),
        '2acos(1-2*0.6666666666666666)': 2 * math.acos(1 - 2 * 0.6666666666666666),
        '2acos(-0.3333333333333333)': 2 * math.acos(-0.3333333333333333),
        '2*(pi-acos(1/3))': 2 * (math.pi - math.acos(1 / 3)),
    }

def caps(Dmm, S):
    out = {}
    for tn, th in thetas().items():
        for Dn, D in [('D/1000', Dmm / 1000), ('D*0.001', Dmm * 0.001)]:
            As = {
                'D2/8(th-sin)': D * D / 8 * (th - math.sin(th)),
                '(th-sin)D2/8': (th - math.sin(th)) * D * D / 8,
