                '(th-sin)*D^2/8': (th - math.sin(th)) * D ** 2 / 8,
                'r2/2(th-sin)': (D / 2) ** 2 / 2 * (th - math.sin(th)),
                '0.5r2(th-sin)': 0.5 * (D / 2) * (D / 2) * (th - math.sin(th)),
            }
            Ps = {'th*D/2': th * D / 2, 'th*(D/2)': th * (D / 2), 'D/2*th': D / 2 * th}
            for (an, A), (pn, P) in itertools.product(As.items(), Ps.items()):
                R = A / P
                for rn, R23 in [('powf(2/3)', R ** (2 / 3)), ('cbrt^2', (R ** (1 / 3)) ** 2), ('cbrt(R*R)', (R * R) ** (1 / 3))]:
                    for qn, q in [
                        ('1/n*A*R23*sqrtS', 1 / N * A * R23 * math.sqrt(S)),
                        ('A*R23*sqrtS/n', A * R23 * math.sqrt(S) / N),
                        ('A/n*R23*sqrtS', A / N * R23 * math.sqrt(S)),
                        ('A*R23*S^0.5/n', A * R23 * S ** 0.5 / N),
                        ('sqrtS/n*A*R23', math.sqrt(S) / N * A * R23),
                        ('A*R23/n*sqrtS', A * R23 / N * math.sqrt(S)),
