#!/usr/bin/env python3
"""Downpipe readings at exact decimal ties (D = k + 0.05 in decimal) for nice flows and depths: compare."""
import sys, json
from fractions import Fraction as F
sys.path.insert(0, '/tmp/hydro-agent')
from lib import *
from smodel import H_CURVES
items = []
for outlet, cs in H_CURVES.items():
    for i, (h, a, b) in enumerate(cs):
        fa, fb = F(str(a)), F(str(b))
        for qn in range(1, 40000):
            q = F(qn, 10)  # one decimal flows
            d = fa + fb * q
            if (d * 100) % 10 == 5 and (d * 100).denominator == 1 and -40 < d < 150:
                # exact tie at this depth knot; also try depths between knots giving ties
                items.append(('storm_size', RawJ('{"kind":"downpipe","flow":%s,"gutter":%d,"length":1000000000,"outlet":"%s"}' % (str(float(q)), h, outlet))))
print(len(items), 'tie cases')
compare(items, verbose=10, label='ties at depth knots')
# between knots: gutter with one decimal, flows integer
items = []
for outlet, cs in H_CURVES.items():
    for (h0, a0, b0), (h1, a1, b1) in zip(cs, cs[1:]):
        for hh in range(1, 100):
            h = F(h0) + F(hh, 10)
            if h >= h1:
                break
            t = (h - h0) / (h1 - h0)
            for qn in range(1, 3000):
                d0 = F(str(a0)) + F(str(b0)) * qn
                d1 = F(str(a1)) + F(str(b1)) * qn
                d = d0 + t * (d1 - d0)
                if (d * 100).denominator == 1 and (d * 100) % 10 == 5 and -40 < d < 150:
                    items.append(('storm_size', RawJ('{"kind":"downpipe","flow":%d,"gutter":%s,"length":1000000000,"outlet":"%s"}' % (qn, str(float(h)), outlet))))
print(len(items), 'tie cases between knots')
compare(items[:20000], verbose=10, label='ties between knots')

