#!/usr/bin/env python3
"""Exact target capacities from the ok boundaries; a wide search of Manning expression orders."""
import sys, json, math, itertools
sys.path.insert(0, '/tmp/hydro-agent')
from lib import serde_f64
data = json.load(open('/tmp/hydro-agent/manb.json'))
N = 0.011

def targets():
    out = []
    for d, s, lo, hi in data:
        lo = serde_f64(lo)
        hi = serde_f64(hi)
        # candidate doubles x near lo - 1e-9 with fl(x + 1e-9) <= lo < ... (q <= x + 1e-9 true at lo, false at hi)
        base = lo - 1e-9
        cands = set()
        for k in range(-8, 9):
            x = base + k * math.ulp(base)
            if lo <= x + 1e-9 and not (hi <= x + 1e-9):
                cands.add(x)
        out.append((d, s, cands))
    return out

T = targets()

def gen(D, S):
    """Yield (name, value) for many capacity expressions (L/min)."""
    ths = {
        'acos(1-2*(2/3))': 2 * math.acos(1 - 2 * (2 / 3)),
        'acos(-1/3)': 2 * math.acos(-1 / 3),
        'acos(1-4/3)': 2 * math.acos(1 - 4 / 3),
        'acos(1-2*.6666666666666666)': 2 * math.acos(1 - 2 * 0.6666666666666666),
        '2(pi-acos(1/3))': 2 * (math.pi - math.acos(1 / 3)),
        'pi+2asin(1/3)': math.pi + 2 * math.asin(1 / 3),
    }
    for tn, th in ths.items():
        s = math.sin(th)
        for dn, Dm in [('D/1000', D / 1000), ('D*1e-3', D * 1e-3), ('D*0.001', D * 0.001)]:
            r = Dm / 2
            areas = {
                'Dm*Dm/8*(th-s)': Dm * Dm / 8 * (th - s),
                '(th-s)*Dm*Dm/8': (th - s) * Dm * Dm / 8,
                'r*r/2*(th-s)': r * r / 2 * (th - s),
                'r*r*(th-s)/2': r * r * (th - s) / 2,
                '0.5*r*r*(th-s)': 0.5 * r * r * (th - s),
                '(th-s)/2*r*r': (th - s) / 2 * r * r,
                'r^2/2*(th-s)': r ** 2 / 2 * (th - s),
                'r^2*(th-s)/2': r ** 2 * (th - s) / 2,
                'Dm^2/8*(th-s)': Dm ** 2 / 8 * (th - s),
                'Dm^2*(th-s)/8': Dm ** 2 * (th - s) / 8,
                '(th-s)*Dm^2/8': (th - s) * Dm ** 2 / 8,
                'r*r*(th-s)*0.5': r * r * (th - s) * 0.5,
                '0.5*(th-s)*r*r': 0.5 * (th - s) * r * r,
                '0.5*r^2*(th-s)': 0.5 * r ** 2 * (th - s),
            }
            perims = {'th*Dm/2': th * Dm / 2, 'Dm*th/2': Dm * th / 2, 'th*r': th * r, 'r*th': r * th, '0.5*th*Dm': 0.5 * th * Dm}
            for (an, A), (pn, P) in itertools.product(areas.items(), perims.items()):
                R = A / P
                r23s = {'R^(2/3)': R ** (2 / 3), 'cbrt(R)^2': (R ** (1 / 3)) ** 2, 'cbrt(R*R)': (R * R) ** (1 / 3),
                        'exp(2/3 lnR)': math.exp(2 / 3 * math.log(R)), 'R^0.6666666666666666': R ** 0.6666666666666666}
                for rn, R23 in r23s.items():
                    sq = math.sqrt(S)
                    qs = {
                        'A*R23*sq/n': A * R23 * sq / N,
                        '1/n*A*R23*sq': 1 / N * A * R23 * sq,
                        'A/n*R23*sq': A / N * R23 * sq,
                        'sq/n*A*R23': sq / N * A * R23,
                        'A*R23/n*sq': A * R23 / N * sq,
                        '(1/n)*A*R23*sq': (1 / N) * A * R23 * sq,
                        'A*R23*(sq/n)': A * R23 * (sq / N),
                        'A*(R23*sq)/n': A * (R23 * sq) / N,
                        'R23*sq*A/n': R23 * sq * A / N,
                        'A*sq*R23/n': A * sq * R23 / N,
                    }
                    for qn, q in qs.items():
                        for un, f in [('*60000', 60000.0), ('*1000*60', None), ('*60*1000', None), ('*1000/60^-1', None)]:
                            if un == '*60000':
                                v = q * 60000.0
                            elif un == '*1000*60':
                                v = q * 1000 * 60
                            elif un == '*60*1000':
                                v = q * 60 * 1000
                            else:
                                v = q * 1000 * 60.0
                            yield (tn, dn, an, pn, rn, qn, un), v

score = {}
for d, s, cands in T:
    for k, v in gen(d, s):
        score[k] = score.get(k, 0) + (v in cands)
best = sorted(score.items(), key=lambda kv: -kv[1])
for k, v in best[:15]:
    print(v, k)
print('of', len(T), 'variants', len(best))

