#!/usr/bin/env python3
"""Manning through the full pipe and the partial-flow ratio, and other structures."""
import sys, json, math, itertools
sys.path.insert(0, '/tmp/hydro-agent')
from manfit3 import T, N

def gen(D, S):
    th_forms = {'t1': 2 * math.acos(1 - 2 * (2 / 3)), 't2': 2 * math.acos(-1 / 3)}
    for tn, th in th_forms.items():
        s = math.sin(th)
        for dn, Dm in [('D/1000', D / 1000)]:
            sq = math.sqrt(S)
            Af = {'pi*Dm*Dm/4': math.pi * Dm * Dm / 4, 'pi/4*Dm*Dm': math.pi / 4 * Dm * Dm, 'pi*Dm^2/4': math.pi * Dm ** 2 / 4,
                  'pi*(Dm/2)^2': math.pi * (Dm / 2) ** 2}
            Rf = {'Dm/4': Dm / 4}
            ratios = {
                'a': (th - s) / (2 * math.pi) * (1 - s / th) ** (2 / 3),
                'b': ((th - s) / (2 * math.pi)) * ((1 - s / th) ** (2 / 3)),
                'c': (th - s) / (2 * math.pi) * ((th - s) / th) ** (2 / 3),
                'd': (th - s) / 2 / math.pi * (1 - s / th) ** (2 / 3),
            }
            arat = {'(th-s)/(2pi)': (th - s) / (2 * math.pi), '(th-s)/2/pi': (th - s) / 2 / math.pi}
            rrat = {'1-s/th': 1 - s / th, '(th-s)/th': (th - s) / th}
            for (an, A), (rn, R) in itertools.product(Af.items(), Rf.items()):
                for qfn, qf in [('1/n*A*R^(2/3)*sq', 1 / N * A * R ** (2 / 3) * sq), ('A*R^(2/3)*sq/n', A * R ** (2 / 3) * sq / N),
                                ('A/n*R^(2/3)*sq', A / N * R ** (2 / 3) * sq)]:
                    for ratn, rat in ratios.items():
                        for un, v in [('*60000', qf * rat * 60000), ('rat first', rat * qf * 60000), ('*60000*rat', qf * 60000 * rat)]:
                            yield (tn, an, qfn, ratn, un), v
                    # partial area and radius via ratios
                    for (a2n, ar), (r2n, rr) in itertools.product(arat.items(), rrat.items()):
                        Ap = A * ar
                        Rp = R * rr
                        for qn, q in [('Ap*Rp^(2/3)*sq/n', Ap * Rp ** (2 / 3) * sq / N), ('1/n*Ap*Rp^(2/3)*sq', 1 / N * Ap * Rp ** (2 / 3) * sq)]:
                            yield (tn, an, a2n, r2n, qn), q * 60000

score = {}
for d, s, cands in T:
    for k, v in gen(d, s):
        score[k] = score.get(k, 0) + (v in cands)
best = sorted(score.items(), key=lambda kv: -kv[1])
for k, v in best[:10]:
    print(v, k)
print('of', len(T), 'variants', len(best))

