#!/usr/bin/env python3
"""manfit3's search under each form of the ok comparison."""
import sys, json, math
sys.path.insert(0, '/tmp/hydro-agent')
from lib import serde_f64
import manfit3
data = json.load(open('/tmp/hydro-agent/manb.json'))
PREDS = {
    'q<=c+tol': lambda q, c: q <= c + 1e-9,
    'q-c<=tol': lambda q, c: q - c <= 1e-9,
    'c>=q-tol': lambda q, c: c >= q - 1e-9,
    'c-q>=-tol': lambda q, c: c - q >= -1e-9,
    'q<c+tol': lambda q, c: q < c + 1e-9,
    'q-tol<=c': lambda q, c: q - 1e-9 <= c,
}
for pn, pred in PREDS.items():
    T = []
    for d, s, lo, hi in data:
        lo = serde_f64(lo)
        hi = serde_f64(hi)
        base = lo - 1e-9
        cands = set()
        for k in range(-12, 13):
            x = base + k * math.ulp(base)
            if pred(lo, x) and not pred(hi, x):
                cands.add(x)
        T.append((d, s, cands))
    score = {}
    for d, s, cands in T:
        seen = {}
        for k, v in manfit3.gen(d, s):
            seen[k] = seen.get(k, False) or (v in cands)
        for k, ok in seen.items():
            score[k] = score.get(k, 0) + ok
    best = sorted(score.items(), key=lambda kv: -kv[1])
    print(pn, best[0][1], best[0][0])

